-- =====================================================================
-- Fritz EV Online Store - database schema (M18 Fritz EV Database)
-- Owner: Mohammed (PB-16)
--
-- Portable SQL: runs on PostgreSQL (Supabase) AND on H2 in PostgreSQL
-- mode (local dev / tests). Keep it that way: no Postgres-only types
-- (SERIAL, JSONB, ENUM, TEXT[]), use GENERATED BY DEFAULT AS IDENTITY.
--
-- Extends the course sample schema (Vehicle, Address, VisitEvent) with
-- vehicle history, colours, interior fabric, users, carts, orders,
-- reviews, test-drive bookings and analytics events.
--
-- !! Running this file DROPS every table. On Supabase run it once from
--    the SQL editor (or start the app once with DB_INIT_MODE=always).
-- =====================================================================

DROP TABLE IF EXISTS visit_events CASCADE;
DROP TABLE IF EXISTS test_drive_bookings CASCADE;
DROP TABLE IF EXISTS test_drive_slots CASCADE;
DROP TABLE IF EXISTS reviews CASCADE;
DROP TABLE IF EXISTS order_items CASCADE;
DROP TABLE IF EXISTS orders CASCADE;
DROP TABLE IF EXISTS cart_item_options CASCADE;
DROP TABLE IF EXISTS cart_items CASCADE;
DROP TABLE IF EXISTS carts CASCADE;
DROP TABLE IF EXISTS vehicle_options CASCADE;
DROP TABLE IF EXISTS customization_options CASCADE;
DROP TABLE IF EXISTS vehicle_history CASCADE;
DROP TABLE IF EXISTS vehicles CASCADE;
DROP TABLE IF EXISTS addresses CASCADE;
DROP TABLE IF EXISTS users CASCADE;

-- ---------------------------------------------------------------------
-- Accounts (M4 Account Manager) - UC-01, UC-02, UC-03
-- password_hash holds a BCrypt hash. Plain-text passwords are NEVER stored.
-- ---------------------------------------------------------------------
CREATE TABLE users (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username        VARCHAR(50)  NOT NULL UNIQUE,
    email           VARCHAR(120) NOT NULL UNIQUE,
    password_hash   VARCHAR(100) NOT NULL,
    first_name      VARCHAR(60),
    last_name       VARCHAR(60),
    role            VARCHAR(20)  NOT NULL DEFAULT 'CUSTOMER'
                    CHECK (role IN ('CUSTOMER', 'ADMIN')),
    verified_owner  BOOLEAN      NOT NULL DEFAULT FALSE,   -- UC-15 gate
    created_at      TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Default billing / shipping addresses (course sample "Address" table)
CREATE TABLE addresses (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id      BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    type         VARCHAR(10)  NOT NULL CHECK (type IN ('BILLING', 'SHIPPING')),
    street       VARCHAR(120) NOT NULL,
    city         VARCHAR(60)  NOT NULL,
    province     VARCHAR(40)  NOT NULL,
    country      VARCHAR(40)  NOT NULL DEFAULT 'Canada',
    postal_code  VARCHAR(12)  NOT NULL,
    phone        VARCHAR(20),
    UNIQUE (user_id, type)
);

-- ---------------------------------------------------------------------
-- Catalogue (M5 Catalog Manager) - UC-04 .. UC-07, hot deals
-- ---------------------------------------------------------------------
CREATE TABLE vehicles (
    id                     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    brand                  VARCHAR(40)   NOT NULL,
    model                  VARCHAR(60)   NOT NULL,
    trim_name              VARCHAR(60),
    model_year             INT           NOT NULL CHECK (model_year BETWEEN 2000 AND 2100),
    shape                  VARCHAR(20)   NOT NULL
                           CHECK (shape IN ('SEDAN', 'SUV', 'TRUCK', 'HATCHBACK', 'COUPE', 'VAN', 'WAGON')),
    vehicle_condition      VARCHAR(10)   NOT NULL CHECK (vehicle_condition IN ('NEW', 'USED')),
    price                  NUMERIC(10,2) NOT NULL CHECK (price >= 0),
    deal_price             NUMERIC(10,2) CHECK (deal_price >= 0),  -- set => vehicle is a hot deal
    mileage_km             INT           NOT NULL DEFAULT 0 CHECK (mileage_km >= 0),
    range_km               INT           NOT NULL CHECK (range_km > 0),
    battery_kwh            NUMERIC(5,1)  NOT NULL CHECK (battery_kwh > 0),
    energy_kwh_per_100km   NUMERIC(4,1)  NOT NULL CHECK (energy_kwh_per_100km > 0), -- used by UC-20
    battery_health_pct     INT           CHECK (battery_health_pct BETWEEN 0 AND 100), -- used EVs, UC-19
    drivetrain             VARCHAR(10)   CHECK (drivetrain IN ('FWD', 'RWD', 'AWD')),
    seats                  INT           CHECK (seats > 0),
    description            VARCHAR(1000),
    image_url              VARCHAR(300),
    quantity               INT           NOT NULL DEFAULT 1 CHECK (quantity >= 0),
    status                 VARCHAR(10)   NOT NULL DEFAULT 'AVAILABLE'
                           CHECK (status IN ('AVAILABLE', 'RESERVED', 'SOLD')),
    created_at             TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_vehicles_brand ON vehicles(brand);
CREATE INDEX idx_vehicles_status ON vehicles(status);

-- Vehicle history report (pre-owned vehicles only) - UC-05 filter, UC-06 details
CREATE TABLE vehicle_history (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    vehicle_id        BIGINT       NOT NULL UNIQUE REFERENCES vehicles(id) ON DELETE CASCADE,
    accident_count    INT          NOT NULL DEFAULT 0 CHECK (accident_count >= 0),
    damage_reported   BOOLEAN      NOT NULL DEFAULT FALSE,
    previous_owners   INT          NOT NULL DEFAULT 1 CHECK (previous_owners >= 0),
    service_records   INT          NOT NULL DEFAULT 0 CHECK (service_records >= 0),
    report_summary    VARCHAR(1000),
    report_date       DATE
);

-- Colours, interior colours, interior fabric, wheels (M6 Vehicle Configurator) - UC-08
CREATE TABLE customization_options (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    category     VARCHAR(20)   NOT NULL
                 CHECK (category IN ('EXTERIOR_COLOUR', 'INTERIOR_COLOUR', 'INTERIOR_FABRIC', 'WHEELS')),
    name         VARCHAR(60)   NOT NULL,
    hex_code     VARCHAR(7),                       -- colours only, e.g. #1E3A8A
    price_delta  NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK (price_delta >= 0),
    UNIQUE (category, name)
);

-- Which options are offered for which vehicle
CREATE TABLE vehicle_options (
    vehicle_id  BIGINT NOT NULL REFERENCES vehicles(id) ON DELETE CASCADE,
    option_id   BIGINT NOT NULL REFERENCES customization_options(id) ON DELETE CASCADE,
    PRIMARY KEY (vehicle_id, option_id)
);

-- ---------------------------------------------------------------------
-- Shopping cart (M7 Cart Manager) - UC-12, UC-13
-- A cart belongs to a user OR to an anonymous session token.
-- ---------------------------------------------------------------------
CREATE TABLE carts (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id        BIGINT      REFERENCES users(id) ON DELETE CASCADE,
    session_token  VARCHAR(64) UNIQUE,
    created_at     TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at     TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE cart_items (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cart_id     BIGINT        NOT NULL REFERENCES carts(id) ON DELETE CASCADE,
    vehicle_id  BIGINT        NOT NULL REFERENCES vehicles(id),
    quantity    INT           NOT NULL DEFAULT 1 CHECK (quantity > 0),
    unit_price  NUMERIC(10,2) NOT NULL CHECK (unit_price >= 0)  -- base (or deal) price + option deltas
);

CREATE TABLE cart_item_options (
    cart_item_id  BIGINT NOT NULL REFERENCES cart_items(id) ON DELETE CASCADE,
    option_id     BIGINT NOT NULL REFERENCES customization_options(id),
    PRIMARY KEY (cart_item_id, option_id)
);

-- ---------------------------------------------------------------------
-- Orders (M8 Order Manager) - UC-14, UC-17
-- NOTE: there is deliberately NO column for card numbers. Cards are passed
-- to the payment adapter (M15) and never persisted.
-- ---------------------------------------------------------------------
CREATE TABLE orders (
    id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id            BIGINT        NOT NULL REFERENCES users(id),
    status             VARCHAR(20)   NOT NULL DEFAULT 'COMPLETED'
                       CHECK (status IN ('PENDING', 'COMPLETED', 'PAYMENT_FAILED', 'CANCELLED')),
    total              NUMERIC(12,2) NOT NULL CHECK (total >= 0),
    ship_street        VARCHAR(120)  NOT NULL,
    ship_city          VARCHAR(60)   NOT NULL,
    ship_province      VARCHAR(40)   NOT NULL,
    ship_country       VARCHAR(40)   NOT NULL,
    ship_postal_code   VARCHAR(12)   NOT NULL,
    created_at         TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_orders_created ON orders(created_at);

CREATE TABLE order_items (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_id         BIGINT        NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
    vehicle_id       BIGINT        NOT NULL REFERENCES vehicles(id),
    quantity         INT           NOT NULL CHECK (quantity > 0),
    unit_price       NUMERIC(10,2) NOT NULL CHECK (unit_price >= 0),
    options_summary  VARCHAR(300)   -- e.g. "Pearl White / Black Vegan Leather / 20in Sport"
);

-- ---------------------------------------------------------------------
-- Reviews (M12 Review Manager) - UC-15, verified EV owners only
-- ---------------------------------------------------------------------
CREATE TABLE reviews (
    id                     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    vehicle_id             BIGINT        NOT NULL REFERENCES vehicles(id) ON DELETE CASCADE,
    user_id                BIGINT        NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    rating                 INT           NOT NULL CHECK (rating BETWEEN 1 AND 5),
    winter_range_km        INT           CHECK (winter_range_km >= 0),
    winter_range_notes     VARCHAR(500),
    home_charging_notes    VARCHAR(500),
    software_update_notes  VARCHAR(500),
    overall_satisfaction   INT           NOT NULL CHECK (overall_satisfaction BETWEEN 1 AND 5),
    comment                VARCHAR(1000),
    created_at             TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (vehicle_id, user_id)          -- one review per owner per vehicle
);

-- ---------------------------------------------------------------------
-- Test drives (M11 Test Drive Scheduler) - UC-11
-- UNIQUE(slot_id) on bookings is the database-level guard against double booking.
-- ---------------------------------------------------------------------
CREATE TABLE test_drive_slots (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    vehicle_id   BIGINT      NOT NULL REFERENCES vehicles(id) ON DELETE CASCADE,
    drive_type   VARCHAR(10) NOT NULL CHECK (drive_type IN ('AT_HOME', 'VIRTUAL')),
    slot_start   TIMESTAMP   NOT NULL,
    slot_minutes INT         NOT NULL DEFAULT 60 CHECK (slot_minutes > 0),
    UNIQUE (vehicle_id, drive_type, slot_start)
);

CREATE TABLE test_drive_bookings (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slot_id     BIGINT       NOT NULL UNIQUE REFERENCES test_drive_slots(id) ON DELETE CASCADE,
    user_id     BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    address     VARCHAR(200),               -- required for AT_HOME drives
    status      VARCHAR(10)  NOT NULL DEFAULT 'BOOKED' CHECK (status IN ('BOOKED', 'COMPLETED')),
    created_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- ---------------------------------------------------------------------
-- Visit events (M14 Analytics Manager) - UC-18, UC-19
-- Mirrors the course sample VisitEvent(day, bid, eventtype) table.
-- ---------------------------------------------------------------------
CREATE TABLE visit_events (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    session_id   VARCHAR(64),
    user_id      BIGINT      REFERENCES users(id) ON DELETE SET NULL,
    vehicle_id   BIGINT      REFERENCES vehicles(id) ON DELETE SET NULL,
    event_type   VARCHAR(10) NOT NULL CHECK (event_type IN ('VIEW', 'CART', 'PURCHASE')),
    created_at   TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_events_created ON visit_events(created_at);
